package pl.dawio.kitgui;

import org.bukkit.Bukkit;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.Listener;
import org.bukkit.plugin.java.JavaPlugin;

public class Main extends JavaPlugin implements Listener {
    private KitManager kitManager;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        kitManager = new KitManager(this);
        getServer().getPluginManager().registerEvents(kitManager, this);
        getLogger().info("KitGUI włączony");
    }

    @Override
    public void onDisable() {
        getLogger().info("KitGUI wyłączony");
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (command.getName().equalsIgnoreCase("kit")) {
            if (!(sender instanceof Player player)) {
                sender.sendMessage("Komenda dostępna tylko dla graczy.");
                return true;
            }
            if (!sender.hasPermission("kitgui.use")) {
                sender.sendMessage("&cNie masz uprawnień.".replace('&','§'));
                return true;
            }
            kitManager.openKitMenu(player);
            return true;
        }
        return false;
    }

    public FileConfiguration getKitsConfig() {
        return getConfig();
    }
}

package pl.dawio.kitgui;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.NamespacedKey;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;

public class KitManager implements Listener {
    private final Main plugin;
    private final NamespacedKey kitKey;

    public KitManager(Main plugin) {
        this.plugin = plugin;
        this.kitKey = new NamespacedKey(plugin, "kit-name");
    }

    public void openKitMenu(Player player) {
        FileConfiguration cfg = plugin.getKitsConfig();
        Set<String> kitIds = cfg.getConfigurationSection("kits").getKeys(false);
        int size = ((kitIds.size() - 1) / 9 + 1) * 9; // najbliższy wielokrotność 9
        Inventory inv = Bukkit.createInventory(null, size, Component.text("Wybierz Kit").color(NamedTextColor.GOLD));
        int slot = 0;
        for (String id : kitIds) {
            String displayName = cfg.getString("kits." + id + ".display-name", id);
            ItemStack item = new ItemStack(Material.CHEST);
            ItemMeta meta = item.getItemMeta();
            meta.displayName(Component.text(displayName).color(NamedTextColor.AQUA));
            List<Component> lore = new ArrayList<>();
            lore.add(Component.text("Kliknij, aby otrzymać kit").color(NamedTextColor.GRAY));
            meta.lore(lore);
            PersistentDataContainer pdc = meta.getPersistentDataContainer();
            pdc.set(kitKey, PersistentDataType.STRING, id);
            item.setItemMeta(meta);
            inv.setItem(slot++, item);
        }
        player.openInventory(inv);
    }

    @EventHandler
    public void onInventoryClick(InventoryClickEvent e) {
        if (!(e.getWhoClicked() instanceof Player player)) return;
        if (e.getView().title().equals(Component.text("Wybierz Kit").color(NamedTextColor.GOLD))) {
            e.setCancelled(true);
            ItemStack clicked = e.getCurrentItem();
            if (clicked == null || clicked.getType().isAir()) return;
            PersistentDataContainer pdc = clicked.getItemMeta().getPersistentDataContainer();
            if (!pdc.has(kitKey, PersistentDataType.STRING)) return;
            String kitId = pdc.get(kitKey, PersistentDataType.STRING);
            giveKit(player, kitId);
            player.closeInventory();
        }
    }

    private void giveKit(Player player, String kitId) {
        FileConfiguration cfg = plugin.getKitsConfig();
        List<String> items = cfg.getStringList("kits." + kitId + ".items");
        if (items.isEmpty()) {
            player.sendMessage(Component.text("Kit nie istnieje lub jest pusty.").color(NamedTextColor.RED));
            return;
        }
        for (String raw : items) {
            // format: material{nbt};amount
            String[] parts = raw.split(";");
            String matPart = parts[0];
            int amount = parts.length > 1 ? Integer.parseInt(parts[1]) : 1;
            ItemStack stack = parseItemStack(matPart, amount);
            if (stack != null) {
                player.getInventory().addItem(stack);
            }
        }
        player.sendMessage(Component.text("Otrzymałeś kit: "+kitId).color(NamedTextColor.GREEN));
    }

    private ItemStack parseItemStack(String definition, int amount) {
        // Przykład: minecraft:iron_sword{Enchantments:[{id:"minecraft:sharpness",lvl:1}]}
        String materialName = definition;
        String nbt = null;
        if (definition.contains("{")) {
            materialName = definition.substring(0, definition.indexOf('{'));
            nbt = definition.substring(definition.indexOf('{'));
        }
        Material mat = Material.getMaterial(materialName.toUpperCase().replace("minecraft:", ""));
        if (mat == null) return null;
        ItemStack stack = new ItemStack(mat, amount);
        if (nbt != null) {
            // Bukkit nie posiada wbudowanego parsera NBT z 1.21, więc używamy ItemStack#addUnsafeEnchantment dla najprostszych przypadków
            // W tym przykładzie obsługujemy jedynie enchantments podane w formacie {Enchantments:[{id:"minecraft:sharpness",lvl:1}]}
            if (nbt.contains("Enchantments")) {
                String enchPart = nbt.substring(nbt.indexOf('[') + 1, nbt.lastIndexOf(']'));
                String[] enchEntries = enchPart.split("},");
                for (String entry : enchEntries) {
                    entry = entry.replace("{", "").replace("}", "");
                    String[] kv = entry.split(",");
                    String id = null;
                    int lvl = 1;
                    for (String kvp : kv) {
                        String[] pair = kvp.split(":");
                        if (pair.length != 2) continue;
                        String key = pair[0].trim();
                        String value = pair[1].trim().replaceAll("\"", "");
                        if (key.equals("id")) id = value.replace("minecraft:", "");
                        if (key.equals("lvl")) lvl = Integer.parseInt(value);
                    }
                    if (id != null) {
                        try {
                            var enchant = org.bukkit.enchantments.Enchantment.getByKey(org.bukkit.NamespacedKey.minecraft(id));
                            if (enchant != null) {
                                stack.addUnsafeEnchantment(enchant, lvl);
                            }
                        } catch (Exception ignored) {}
                    }
                }
            }
        }
        return stack;
    }
}
